// AETHWYRD — data classes mirroring Data/Monsters/motion.json (generated by Tools/monster_gen/motion.js).
// Public fields + [Serializable] so UnityEngine.JsonUtility can read them. Unknown JSON fields are ignored.
using System;

namespace Ascend.Monsters
{
    [Serializable] public class MotionFile { public int version; public int fps = 30; public int count; public MonsterProfile[] species; }

    [Serializable]
    public class MonsterProfile
    {
        public string speciesId, name, rigKey, rigVia, unityAvatar, animSetId;
        public float sizeMeters, prefabScale, heightM, lengthM, widthM;
        public PhysicsProfile physics;
        public NavProfile navAgent;
        public LocomotionProfile locomotion;
        public MenaceProfile menace;
        public ElementProfile element;
        public BehaviorProfile behavior;
        public TimingProfile timing;
        public AttackTiming[] attacks;
        public SpringDef[] springs;
        public PartDef[] parts;
        public HurtboxDef[] hurtboxes;
        public string[] procedural;
        public AudioProfile audio;
        public Signature signature;

        public AttackTiming FindAttack(string attackId)
        {
            if (attacks == null) return null;
            foreach (var a in attacks) if (a.attackId == attackId) return a;
            return null;
        }
    }

    [Serializable]
    public class PhysicsProfile
    {
        public float massKg, gravityScale, linearDrag, buoyancy;
        public string colliderType, colliderAxis;
        public float colliderRadius, colliderHeight, knockbackResist;
        public string launchable, ragdoll, deathStyle;
        public int poise;
        public float hitstopMult, footstepShake;
    }

    [Serializable] public class NavProfile { public float radius, height, speed, walkSpeed, angularSpeed, acceleration, stoppingDistance, baseOffset; public string areaMask; }
    [Serializable] public class Gait { public string name; public float speed, froude; }

    [Serializable]
    public class LocomotionProfile
    {
        public Gait[] gaits;
        public float playRate, turnDegPerSec, accel, jumpHeight, flySpeed;
        public string canClimb, canSwim, canFly, hovers;
        public bool blink;
    }

    [Serializable]
    public class MenaceProfile
    {
        public int level;
        public string label, posture;
        public int steppedAnimFps, blinkPerMin;
        public float squashStretch, audioRevealRadius;
        public bool freezeWhenObserved;
        public string[] notes;
    }

    [Serializable] public class ElementProfile { public string name, footstepFx, trailFx; public string[] idleFx, notes; }
    [Serializable] public class BehaviorProfile { public string name, aiPattern; public float alertRadius, leashRadius, preferredRange, circleRadius, retreatHpPct; public string[] notes; }
    [Serializable] public class TimingProfile { public float minTelegraphSec, minRecoverySec, sizeTimeMult, rankFactor; }
    [Serializable] public class AnimFrames { public int windup, active, recovery; }

    [Serializable]
    public class AttackTiming
    {
        public string attackId, slot, kind, telegraph, hitboxBone, notes;
        public float windupSec, activeSec, recoverySec, windupJitter, feintChance, hitboxRadius, lungeDistance;
        public float trackingWindupDegPerSec, trackingActiveDegPerSec;
        public AnimFrames animFrames;
        public float TotalSec => windupSec + activeSec + recoverySec;
    }

    [Serializable] public class SpringDef { public string root; public int length; public float stiffness, damping, gravity; }
    [Serializable] public class PartDef { public string partId, bone, materialTag, onBreak; public int hp; }

    [Serializable]
    public class HurtboxDef
    {
        public string bone, shape, partId;
        public float radius, height, dmgMult = 1f;
        public float[] center; // Blender space (x, y, z) at species size
        public float[] size;   // box size, Blender space
    }

    [Serializable] public class AudioProfile { public string footstep; public float vocalPitch; }
    [Serializable] public class Signature { public string summary, death; public string[] idle, movement, combat, hitReact, blender, unity; }
}
